#' Prepare a GBPP network data object
#'
#' Construct Berman-Turner quadrature data for a spatial point process on a
#' linear network using [spatstat.linnet::linequad()], preserving native network
#' topology (`seg`, `tp`) via `attr(Q, "situ")` and evaluating linear-network
#' covariates at the quadrature locations.
#'
#' @details
#' `prepare_gbpp_network()` uses deterministic equal-spacing quadrature points
#' generated by [spatstat.linnet::linequad()]. Consequently, while Poisson
#' quadrature weights (\eqn{v_i}) conserve total network length \eqn{|\mathcal{L}|}
#' exactly, logistic dummy intensity (`dummy_intensity`) is derived
#' deterministically as an approximate proxy rather than an exact random
#' binomial/Poisson dummy point process as in Baddeley et al. (2014).
#'
#' @param point_pattern An `lpp` object containing the observed points.
#' @param covariates A named list of `linim` or `linfun` covariates defined on
#'   the same linear network as `point_pattern`. Numeric and factor-valued
#'   covariates are supported.
#' @param nd Number of dummy quadrature points per network segment, as used by
#'   [spatstat.linnet::linequad()].
#'
#' @param statistical_weight Optional numeric vector of custom statistical weights.
#' @param interaction_integral Optional numeric vector or scalar of spatial interaction
#'   integrals for iteratively weighted objectives.
#'
#' @return A `gbpp_data` object with `type = "network"`, containing covariate data
#'   `X`, binary indicator `y`, network point pattern `locations` (`lpp`),
#'   quadrature weights `quadrature_weight`, approximate `dummy_intensity`,
#'   linear network `window` (`linnet`), and `metadata`.
#'
#' @references
#' Ang, Q. W., Baddeley, A., & Nair, G. (2012). Geometrically corrected second
#' order analysis of events on a linear network, with applications to ecology and
#' criminology. *Scandinavian Journal of Statistics*, 39(4), 591--617.
#' \doi{10.1111/j.1467-9469.2011.00762.x}
#'
#' Baddeley, A., Nair, G., Rakshit, S., McSwiggan, G., & Davies, T. M. (2021).
#' Analysing point patterns on networks --- A review. *Spatial Statistics*,
#' 42, 100435. \doi{10.1016/j.spasta.2020.100435}
#'
#' @seealso [prepare_gbpp()], [prepare_quad_data()], [est_net_interaction()],
#'   [fit_gbpp()]
#'
#' @examples
#' if (requireNamespace("spatstat.data", quietly = TRUE) &&
#'   requireNamespace("spatstat.random", quietly = TRUE)) {
#'   data(simplenet, package = "spatstat.data")
#'   pts <- spatstat.linnet::runiflpp(20, L = simplenet)
#'   cov_x <- spatstat.linnet::linfun(function(x, y, seg, tp) x, L = simplenet)
#'   dat <- prepare_gbpp_network(pts, covariates = list(x = cov_x), nd = 50L)
#'   print(dat)
#' }
#' @export
prepare_gbpp_network <- function(
  point_pattern,
  covariates = list(),
  nd = 1000L,
  statistical_weight = NULL,
  interaction_integral = NULL
) {
  if (!inherits(point_pattern, "lpp")) {
    stop("`point_pattern` must be an `lpp` object.", call. = FALSE)
  }

  if (!is.list(covariates)) {
    stop(
      "`covariates` must be a list of `linim` or `linfun` objects.",
      call. = FALSE
    )
  }

  if (length(covariates) > 0L) {
    if (is.null(names(covariates)) ||
      anyNA(names(covariates)) ||
      any(names(covariates) == "")) {
      stop("All network covariates must be named.", call. = FALSE)
    }

    if (anyDuplicated(names(covariates))) {
      stop(
        "Network covariate names must be unique.",
        call. = FALSE
      )
    }

    invalid <- !vapply(
      covariates,
      function(z) {
        inherits(z, "linim") || inherits(z, "linfun")
      },
      logical(1)
    )

    if (any(invalid)) {
      stop(
        "All network covariates must be `linim` or `linfun` objects.",
        call. = FALSE
      )
    }

    network <- spatstat.linnet::as.linnet(point_pattern)
    .gbpp_check_same_linnet(
      covariates,
      network,
      paste0(
        "All network covariates must be defined on the same ",
        "linear network as `point_pattern`."
      )
    )
  }

  if (length(nd) != 1L ||
    !is.numeric(nd) ||
    !is.finite(nd) ||
    nd <= 0 ||
    nd != as.integer(nd)) {
    stop(
      "`nd` must be one positive integer.",
      call. = FALSE
    )
  }

  nd <- as.integer(nd)

  Q <- spatstat.linnet::linequad(
    point_pattern,
    nd = nd
  )

  # Preserve native lpp object with (x, y, seg, tp) so overpass crossings remain distinct
  U <- attr(Q, "situ")
  if (is.null(U) || !inherits(U, "lpp")) {
    U <- spatstat.linnet::as.lpp(
      spatstat.geom::union.quad(Q),
      L = point_pattern$domain
    )
  }

  y <- as.integer(spatstat.geom::is.data(Q))
  v <- spatstat.geom::w.quad(Q)
  dummy_intensity <- calc_net_dummy_intensity(
    y = y,
    quadrature_weight = v
  )

  X <- data.frame(
    row.names = seq_len(length(y)),
    check.names = FALSE
  )

  if (length(covariates) > 0L) {
    X <- as.data.frame(
      lapply(covariates, function(z) {
        if (inherits(z, "linfun")) {
          z(U$data$x, U$data$y, U$data$seg, U$data$tp)
        } else {
          z[U]
        }
      }),
      check.names = FALSE
    )

    names(X) <- names(covariates)
  }

  if (nrow(X) != length(y)) {
    stop(
      "Network covariate evaluation produced an invalid number of rows.",
      call. = FALSE
    )
  }

  if (anyNA(X)) {
    stop(
      "Network covariates contain missing values at quadrature locations.",
      call. = FALSE
    )
  }

  if (!is.null(interaction_integral) &&
    is.numeric(interaction_integral) &&
    length(interaction_integral) == 1L) {
    interaction_integral <- rep(interaction_integral, length(y))
  }

  out <- new_gbpp_data(
    X = X,
    y = y,
    locations = U,
    quadrature_weight = v,
    dummy_intensity = rep(dummy_intensity, length(y)),
    statistical_weight = statistical_weight,
    interaction_integral = interaction_integral,
    window = point_pattern$domain,
    type = "network",
    metadata = list(
      point_pattern = point_pattern,
      quadrature = Q,
      covariates = covariates,
      quadrature_method = "linequad"
    )
  )
  validate_gbpp_data(out, objective = NULL)
  out
}
